import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['DATABASE'] = os.environ.get('DB_PATH', '/data/app.db')
app.config['HMAC_SECRET'] = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_signature(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        sig = request.headers.get('X-Request-Signature', '')
        ts = request.headers.get('X-Timestamp', '')
        body = request.get_data(as_text=True)
        expected = hmac.new(app.config['HMAC_SECRET'].encode(), 
                          f"{ts}:{body}".encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 403
        return f(*args, **kwargs)
    return decorated

def init_db():
    db = sqlite3.connect(app.config['DATABASE'])
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY, name TEXT, category TEXT,
        price REAL, stock INTEGER, supplier_code TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT, action TEXT,
        query_text TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP)''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY, key_hash TEXT, owner TEXT,
        permissions TEXT, revoked INTEGER DEFAULT 0)''')
    db.commit()
    db.close()

@app.route('/api/products/search', methods=['GET'])
def search_products():
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort', 'name')

    # Input validation for price range
    try:
        min_p = float(min_price)
        max_p = float(max_price)
    except ValueError:
        return jsonify({'error': 'invalid price range'}), 400

    db = get_db()

    # Build query with parameterized category filter
    base_query = "SELECT id, name, category, price, stock FROM products WHERE price BETWEEN ? AND ?"
    params = [min_p, max_p]

    if category:
        base_query += " AND category = ?"
        params.append(category)

    # Sort - validated against allowlist... but sort_by is used directly
    allowed_sorts = ['name', 'price', 'stock', 'category']
    if sort_by not in allowed_sorts:
        # Fallback: use the raw value assuming it might be a compound sort
        # e.g., "name ASC" or "price DESC"
        base_query += f" ORDER BY {sort_by}"
    else:
        base_query += f" ORDER BY {sort_by}"

    try:
        # Log the query for debugging
        db.execute("INSERT INTO audit_log (action, query_text) VALUES (?, ?)",
                  ('search', base_query))
        db.commit()

        cursor = db.execute(base_query, params)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    db = get_db()
    product = db.execute('SELECT * FROM products WHERE id = ?', (product_id,)).fetchone()
    if product is None:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(product))

@app.route('/api/products', methods=['POST'])
@require_signature
def create_product():
    data = request.get_json()
    required = ['name', 'category', 'price', 'stock']
    if not all(k in data for k in required):
        return jsonify({'error': 'missing fields'}), 400
    db = get_db()
    db.execute('INSERT INTO products (name, category, price, stock, supplier_code) VALUES (?, ?, ?, ?, ?)',
              (data['name'], data['category'], data['price'], data['stock'], data.get('supplier_code', '')))
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
